import{_ as i,l as n,o as t,c as l,v as r,p as s,x as e,d as m,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"VIX 期货定价","description":"","frontmatter":{"title":"VIX 期货定价","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vix-futures.md","filePath":"quant/vix-futures.md","lastUpdated":1789023840000}'),V={name:"quant/vix-futures.md"};function X(E,a,d,u,c,B){const o=n("Mermaid");return t(),l("div",null,[a[1]||(a[1]=r('<h1 id="vix-期货定价" tabindex="-1">VIX 期货定价 <a class="header-anchor" href="#vix-期货定价" aria-label="Permalink to &quot;VIX 期货定价&quot;">​</a></h1><div class="epigraph"><p>VIX 期货的标的不是现货指数的已实现方差，而是未来某一时刻那张三十天香草条带的平方根；定价因而落在方差曲线的凸性上，而不是落在对 VIX 现货做简单贴现。</p><footer>—— 指数定义见 CBOE VIX 方法说明书；早期波动期货见 Grünbichler and Longstaff, Journal of Banking &amp; Finance, 1996；曲线框架对照 Bergomi</footer></div><p><a href="/quant/dupire-calib">上一课</a>把局部波动校准写成病态反问题：先造无套利 \\(w(k,T)\\)，再用 \\(\\partial_T w/g\\) 抽出 \\(\\sigma_{\\mathrm{loc}}\\)；动态缺陷要靠 SLV 或随机方差，不能靠更细的校准网格。<a href="/quant/variance-swap-vix">方差互换与 VIX</a> 已经写出指数本身的条带复制。缺口是交易的主要工具——VIX 期货：盯的是结算时刻的 VIX，而该指数已是当时起三十天方差互换的平方根。本课写凸性、期限结构升水与模型定价，不重推导条带公式。标的是未来的三十天线，不是路径已实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若标的是可交割现货 \\(S\\)，期货在利率确定时是 \\(\\mathbb{E}^{\\mathbb{Q}}[S_T]\\)（适当测度）。VIX 不是可交易现货：复制组合每天随期权集改写，且指数是方差的凹函数（开方）。Jensen 给出</p> \\[\\mathbb{E}\\bigl[\\sqrt{X}\\bigr]\\lt \\sqrt{\\mathbb{E}[X]}, \\]<p>\\(X\\) 为未来三十天方差。于是 VIX 期货低于「未来方差互换公平值的平方根」——差一项凸性调整，随 vol-of-vol 与剩余期限增大。把现货 VIX 当成期货的持有成本标的去贴现，等于忽略：指数不可持有、开方凹性、以及 \\(T\\) 时刻的条带与今天的条带不是同一组期权。</p><p>期限结构 \\(T\\mapsto F_{t,T}\\) 在多数年份呈 contango：远月期货高于近月，展期空头吃升水、多头付升水。这与商品库存的 Working 曲线不是同一机制：这里没有仓单，升水主要来自方差风险溢价与均值回复——市场为尾部保护预付，近端隐含方差被顶高，远端向长期均值回落。问题是把升水拆成：凸性（模型技术项）、风险溢价（补偿卖方差）、以及指数定义与期货结算规则的基差。</p><h3 id="标的是未来的三十天线-不是路径已实现" tabindex="-1">标的是未来的三十天线，不是路径已实现 <a class="header-anchor" href="#标的是未来的三十天线-不是路径已实现" aria-label="Permalink to &quot;标的是未来的三十天线，不是路径已实现&quot;">​</a></h3><p>OTC 方差互换对 \\([t,t+h]\\) 的已实现二次变差结算。VIX 期货在 \\(T\\) 结算的是 \\(\\mathrm{VIX}_T\\)，即当时市场对 \\([T,T+\\tau]\\) 的<strong>隐含</strong>方差开方。即使你对冲了从今天到 \\(T\\) 的已实现方差，仍暴露于 \\(T\\) 时刻微笑是否还在、翼部是否还贵。这是「方差互换」与「VIX 期货」之间的基差来源，也是用现货 VIX 去对冲期货会留下 roll 与微笑风险的原因。Grünbichler–Longstaff（1996）在 VIX 修订之前就把波动当作均值回复扩散来写期货与期权；现行指数改为条带复制之后，状态变量更自然的是整条远期方差曲线，而不是一个瞬时 \\(\\sigma_t\\)。</p><p><span class="marginnote">报价惯例是波动率点。合同乘数（如每点 1000 美元）把点变成美元。PnL 归因若用方差单位，必须先把点平方再差分化，否则凸性被算进「alpha」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>从方差曲线到期货。</strong> 记远期瞬时方差为 \\(\\xi_t(u)\\)。理想连续复制下，\\(\\mathrm{VS}_{T,T+\\tau}=\\frac1\\tau\\int_T^{T+\\tau}\\xi_T(u)\\,\\mathrm{d}u\\)。VIX 期货是该积分开方（再乘 100）的条件期望。Heston 只有一个 \\(v_t\\)，蕴含的 \\(\\xi\\) 是指数型，Zhang–Zhu（2006）一类仿射规格可以写出矩，再对开方做近似或模拟。曲线不呈指数时，仿射会同时错方差互换与 VIX 期货。Bergomi 把今日 \\(\\xi_0\\) 从市场填入，期货变成曲线因子在 \\(T\\) 时刻的泛函，用对数正态曲线的矩或蒙特卡洛估 \\(\\mathbb{E}[\\sqrt{\\int\\xi}]\\)。粗糙核抬高短端 vol-of-vol，凸性调整更大，近月期货相对「方差开方」掉得更多。</p><p><strong>复制与对冲。</strong> 理论对冲是一篮子到期落在 \\([T,T+\\tau]\\) 附近的 SPX 香草，权重随 \\(T\\) 临近收敛到 CBOE 条带。实务用可交易的 SPX 期权、VIX 期权与日历，并接受基差：上市到期与三十天整数不重合、执行价网格与官方规则不完全相同。对冲比应对 \\(\\xi\\) 的分桶敏感（短方差、长方差），而不是单一 Vega。Mencía–Sentana 把 VIX 衍生品估值写成仿射或二次项规格，强调水平与 vol-of-vol 因子；交易台语言更接近 Bergomi 的快慢方差。</p><p><strong>升水的交易。</strong> 空头展期吃 contango，等价于持续卖出近端方差风险溢价，回撤发生在 VIX 曲线翻成 backwardation 的危机日——与 <a href="/quant/variance-risk-premium">波动率风险溢价</a> 同一类资金需求。这不是无风险套利。定价模型的用途是：把当前曲线形状拆成「公允凸性」与「额外溢价」，而不是预测 VIX 现货的点位。</p><h3 id="开方凸性与仿射矩" tabindex="-1">开方凸性与仿射矩 <a class="header-anchor" href="#开方凸性与仿射矩" aria-label="Permalink to &quot;开方凸性与仿射矩&quot;">​</a></h3><p>若 \\(X\\sim\\) 对数正态或已知前两矩，可用</p> \\[\\mathbb{E}[\\sqrt{X}]\\approx\\sqrt{\\mathbb{E}[X]}\\Bigl(1-\\frac14\\frac{\\mathrm{Var}(X)}{(\\mathbb{E}[X])^2}+\\cdots\\Bigr) \\]<p>把凸性写成方差的相对波动。\\(\\mathrm{Var}(X)\\) 来自 \\(\\xi\\) 在 \\([T,T+\\tau]\\) 上的联合波动，短端核越糙、\\(\\eta\\) 越大、剩余时间越长（在均值回复拉回来之前），调整越大。Heston 的 \\(\\kappa\\) 大则凸性小，往往低估近月 VIX 期货相对方差互换的折价。校准若只用 SPX 香草、不用 VIX 期货，这一项是样本外检验；若把期货也纳入目标，则在用市场给 vol-of-vol 的期限结构加锚。</p>',19)),(t(),s(p,null,{default:e(()=>[h(o,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20Strip%5B%22T%20%E6%97%B6%E5%88%BB%20SPX%20%E6%9D%A1%E5%B8%A6%22%5D%20--%3E%20VIX%5B%22VIX_T%20%3D%20100%20sqrt(VS)%22%5D%0A%20%20Xi%5B%22%E8%BF%9C%E6%9C%9F%E6%96%B9%E5%B7%AE%E6%9B%B2%E7%BA%BF%20%CE%BE%22%5D%20--%3E%20VS%5B%22VS_T%20%3D%20%E7%A7%AF%E5%88%86%20%CE%BE%20%2F%20%CF%84%22%5D%0A%20%20VS%20--%3E%20VIX%0A%20%20VIX%20--%3E%20Fut%5B%22F%20%3D%20E%5BVIX_T%5D%22%5D%0A%20%20Eta%5B%22vol-of-vol%20%2F%20%E7%B2%97%E7%B3%99%E6%A0%B8%22%5D%20--%3E%20Cvx%5B%22%E5%BC%80%E6%96%B9%E5%87%B8%E6%80%A7%22%5D%0A%20%20Cvx%20--%3E%20Fut%0A%20%20RP%5B%22%E6%96%B9%E5%B7%AE%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%20--%3E%20Term%5B%22%E6%9C%9F%E8%B4%A7%E6%9C%9F%E9%99%90%E5%8D%87%E6%B0%B4%22%5D%0A%20%20Fut%20--%3E%20Term%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>VIX 指数已经把微笑积成一个数；期货再把这个数在时间上做成鞅（期货测度下）。曲线动态决定「这个数以后怎么随机翻动」：均值回复使远月向长期水平靠拢，负相关使现货崩盘时整条近端 \\(\\xi\\) 上跳、期货曲线可以一夜之间从 contango 翻成倒挂。开方把高方差状态压低权重，故期货对尾部的敏感弱于方差互换本身——买 VIX 期货当崩盘保险，买的是 \\(\\sqrt{\\mathrm{VS}}\\) 而非 \\(\\mathrm{VS}\\)，保险效率低于直接买方差或买虚值看跌条带。这是产品选择问题，不是定价公式的 bug。</p><p>结算规则：CBOE 用开盘拍卖特殊结算价（VRO 一类），与收盘 VIX 可以有缺口。模型若用收盘条带校准、用结算价归因，基差会进入「模型误差」。历史序列还要声明 2003 年指数修订：旧 VXO 与现行 VIX 不可混接。周期权纳入规则的变更会移动现货 VIX 的微观结构，期货远月相对钝一些。</p><h3 id="与-otc-方差互换、vix-期权的三角" tabindex="-1">与 OTC 方差互换、VIX 期权的三角 <a class="header-anchor" href="#与-otc-方差互换、vix-期权的三角" aria-label="Permalink to &quot;与 OTC 方差互换、VIX 期权的三角&quot;">​</a></h3><p>同一 \\(\\xi\\) 必须同时服务：今日方差互换期限结构、SPX 香草偏斜、VIX 期货曲线。只贴前两张、第三张系统性偏高或偏低，说明凸性（vol-of-vol）或风险溢价期限结构不对。VIX 期权的标的是期货，隐含波动是对 \\(\\sqrt{\\mathrm{VS}}\\) 的微笑，再经一层凸性，不能直接当成 SPX 的 \\(\\sigma_{\\mathrm{imp}}\\)。用 VIX 期权去校准粗糙 \\(H\\) 或 Bergomi 的 \\(\\eta\\)，信息与 SPX 短端偏斜相关但不重复——前者更干净地看到方差自身的波动。</p><p><span class="marginnote">contango 不是「期货一定高估实现 VIX」。事后平均实现可以低于期货，那是溢价；也可以在一段样本里期货偏低。用历史平均 roll 当未来收益，忽略了翻倒挂的尾部。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>复制假设欧式、连续 \\(K\\)、无跳或跳被条带吸收。跳跃使对数复制与二次变差分家，VIX 作为条带仍有定义，但与已实现方差的保险关系出现缺口，见复制篇。期货保证金与涨跌停（若有）改变可交易性，不改变 \\(\\mathbb{E}[\\mathrm{VIX}_T]\\) 的定义。A 股与欧洲波动指数有各自的条带规则，不能把 VIX 模型换标的即用。</p><p>Grünbichler–Longstaff 是波动作为资产的早期期货公式；CBOE 白皮书是指数定义；Bergomi 与 Bayer–Friz–Gatheral 提供曲线与粗糙核。不要把「VIX 期货定价」写成 1994 年 Dupire 的应用——局部波动钉的是 SPX 香草边际，不自动给出未来条带平方根的期望。也不要把期货升水写成 Keynes 商品正常贴水：这里没有存货便利收益。</p><p><span class="marginnote">用现货 VIX 减随后三十天已实现波动，测的是方差风险溢价的一个代理；用近月期货减随后结算 VIX，测的是期货风险溢价。两套数字相关，期限与开方凸性不同，不能互相替代去写策略。</span></p><p><span class="marginnote">模型若在风险中性下校准期货曲线至零残差，vol-of-vol 里已经含溢价。再用历史方差曲线 PCA 去「验证」同一 \\(\\eta\\)，量纲会对不上——那是两个测度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VIX 期货是 \\(\\mathbb{E}^{\\mathbb{Q}}[\\mathrm{VIX}_T]\\)，标的为未来三十天条带的平方根，不是现货已实现方差。</li><li>开方凹性产生相对方差互换的凸性折价；折价随 vol-of-vol 与粗糙核增大。</li><li>期限升水主要来自方差风险溢价与均值回复，空头展期赚溢价、在倒挂日回撤。</li><li>定价应在远期方差曲线上进行，使香草、方差互换与期货共用 \\(\\xi\\)；Heston 指数曲线常常不够。</li><li>对冲是未来条带的近似复制，现货 VIX 不是持有成本标的。</li><li>出处：CBOE <em>VIX White Paper</em>；Grünbichler and Longstaff, <em>JBF</em>, 1996；对照 Bergomi；粗糙核见 Bayer, Friz and Gatheral, 2016；复制见 Carr and Madan。</li></ul>',13))])}const _=i(V,[["render",X]]);export{b as __pageData,_ as default};
